void resetTimerParams(void)
{
    startTime = 0;
    pausedTime = 0;
    setArcValue = 0;
    arcTimeInSec = 0;
    // totalTimeInSec = MIN_TO_SEC(maxArcValue);
    if (meditation_timer) {
        lv_timer_delete(meditation_timer);
        meditation_timer = NULL;
        _ui_state_modify(ui_medPauseBtn, LV_STATE_CHECKED, _UI_MODIFY_STATE_REMOVE);
    }
    setTimeLabels(totalTimeInSec, arcTimeInSec);
    lv_arc_set_value(ui_meditationTimer, setArcValue);
}

void ui_event_medPauseBtn(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    // static int lastMaxArcValue = maxArcValue;
    if (event_code == LV_EVENT_PRESSED) {
        _ui_state_modify(ui_medPauseBtn, LV_STATE_CHECKED, _UI_MODIFY_STATE_TOGGLE);

    }
    else if (event_code == LV_EVENT_LONG_PRESSED) {
        resetTimerParams();
        timerIsUp(true, true);
    }
    else{
        return;
    }
}

void setTimeLabels(uint32_t remainingTime, uint32_t passedTime)
{
    int min = MIN_FROM_SEC(remainingTime);
    int sec = SEC_REMAIN(remainingTime);
    if (min < 0 || min > 59) min = 60;
    if (sec < 0 || sec > 59) sec = 60;
    sprintf(timeRemainStr, "%02d:%02d", min, sec);
    lv_label_set_text(ui_medTimeRemain, timeRemainStr);
    
    min = MIN_FROM_SEC(passedTime);
    sec = SEC_REMAIN(passedTime);
    if (min < 0 || min > 59) min = 60;
    if (sec < 0 || sec > 59) sec = 60;
    sprintf(timePassedStr, "- %02d:%02d", min, sec);
    lv_label_set_text(ui_medTimePassed, timePassedStr);
}

void timerIsUp(bool isFalse, bool navTrue)
{
    _ui_flag_modify(ui_medTimeRemain,  LV_OBJ_FLAG_HIDDEN, isFalse);
    _ui_flag_modify(ui_medTimePassed,  LV_OBJ_FLAG_HIDDEN, isFalse);
    _ui_flag_modify(ui_medPauseBtn,    LV_OBJ_FLAG_HIDDEN, isFalse);
    _ui_flag_modify(ui_medTimeIsUpLbl, LV_OBJ_FLAG_HIDDEN, !isFalse);
    lv_arc_set_value(ui_meditationTimer, isFalse ? 0 : totalTimeInSec);
    navigatingWidgets = navTrue;
    if(!navTrue)lv_group_focus_obj(ui_HiddenMedScrBtn);
}


void updateTimer()
{
    if (!timerRunning) return;
    
    unsigned long elapsedTime = TIME_IN_SEC - startTime;

    if (elapsedTime != arcTimeInSec && elapsedTime <= totalTimeInSec) {
        arcTimeInSec = elapsedTime;
        setArcValue = elapsedTime; // if set in seconds
        lv_arc_set_value(ui_meditationTimer, setArcValue);

        uint32_t remainingTime = totalTimeInSec - arcTimeInSec;
        setTimeLabels(remainingTime, arcTimeInSec);

        if (arcTimeInSec >= totalTimeInSec) {
            timerRunning = false;  // Stop when countdown ends
            resetTimerParams();
            timerIsUp(false, false);
        }
    }
}


void ui_event_medScreenEvent(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    if (event_code == LV_EVENT_CANCEL) {
        timerIsUp(true, false);
    }  
}

void setTimerValues(uint32_t time, bool startTimer)
{
    arcTimeInSec = 0;
    totalTimeInSec = time;
    // setTimeLabels(totalTimeInSec, arcTimeInSec);
    _ui_state_modify(ui_medPauseBtn, LV_STATE_CHECKED, _UI_MODIFY_STATE_ADD);
    if(startTimer)
    {
        resetTimerParams();
        timerRunning = false;
        // controlMedTimer();
    }
}
//checks the state of timer, start and pauses/resumes it
void controlMedTimer()
{
    if (!timerRunning) {
        timerRunning = true;
        startTime = TIME_IN_SEC - pausedTime;
        // Create LVGL timer to update every second
        if (!meditation_timer) {  // Avoid multiple timers
            meditation_timer = lv_timer_create(updateTimer, 1000, NULL);
        }
        else
        {
            lv_timer_resume(meditation_timer);
        }
        timerIsUp(true, true);
    } else {
        timerRunning = false;
        
        // Pause the timer
        if (meditation_timer) {
            lv_timer_pause(meditation_timer);
            pausedTime = TIME_IN_SEC - startTime;
        }
    }
}